66: function drawUnit(u){let x=u.x,y=u.y,h=u.hero;ctx.fillStyle='#10201566';ctx.fillRect(x-8,y+7,16,3);if(u.team===1){ctx.fillStyle='#263b55';ctx.fillRect(x-8,y+9,16,2)}else{ctx.fillStyle='#572e2b';ctx.fillRect(x-8,y+9,16,2)}if(u.isPlayer){ctx.strokeStyle='#e4ec93';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y+3,11,14,0,0,Math.PI*2);ctx.stroke()}if(u.buff>0){ctx.strokeStyle='#c7ef74aa';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y-3,13+Math.sin(frame*.2)*2,0,Math.PI*2);ctx.stroke()}if(u.hit>0){ctx.fillStyle='#fff5db';ctx.fillRect(x-8,y-15,16,22)}drawSprite(ctx,x,y,h,u.faceX<0?-1:1,1);let bw=19,by=y-22;ctx.fillStyle='#19201c';ctx.fillRect(x-bw/2-1,by-1,bw+2,4);ctx.fillStyle=u.team===1?'#70c8e8':'#e87566';ctx.fillRect(x-bw/2,by,bw*Math.max(0,u.hp/u.maxHp),2);if(u.isPlayer){ctx.fillStyle='#dce78e';ctx.fillRect(x-3,y-27,6,2)}}
