import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/linux.json'), 'utf8'))
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true })
const errors = []
try {
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true })
  page.on('pageerror', e => errors.push(e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
  await page.route('**/game.js', async route => {
    const response = await route.fetch()
    const body = (await response.text()).replace('updateLevel();roster();renderHeroInfo();initProps();render();\n})();', 'updateLevel();roster();renderHeroInfo();initProps();render();window.__gameTest={get:()=>({player,allies,enemies,running}),heroes,activateTransformation,setTransformation,transformed,skillsFor,powerFor,defenseFor,rangeFor,gainCharge,damageTarget,castSkill,update,drawUnit};\n})();')
    await route.fulfill({ response, body })
  })
  await page.goto('http://127.0.0.1:3002', { waitUntil: 'load' })
  await page.locator('#start-button').click()
  const results = await page.evaluate(() => {
    const t=window.__gameTest,s=t.get(),p=s.player
    const result={}
    // Damage, defeat, and nearby-fight charge sources.
    const foe=s.enemies[0]; p.transformCharge=0; p.transformCD=0; foe.x=p.x+20; foe.y=p.y
    t.damageTarget(foe,20,p); result.hitCharge=p.transformCharge>0
    foe.hp=1;foe.alive=true;t.damageTarget(foe,1000,p);result.defeatCharge=p.transformCharge>=22
    p.transformCharge=0;t.update(.2);result.participationCharge=p.transformCharge>0
    // Exercise every hero with a transformation, including live mobile activation.
    const transformedHeroes=t.heroes.filter(h=>h.transform).map(h=>h.id)
    let transformedCount=0,skillCount=0
    for(const h of t.heroes.filter(h=>h.transform)){
      p.hero=h;p.hp=Math.max(1,p.maxHp-10);p.maxHp=h.hp;p.hp=h.hp-10;p.transformCharge=100;p.transformCD=0;p.transformTime=0;p.skillCD=[0,0,0];p.ch=h.id==='naruto'?92:80;p.maxCh=p.ch
      t.activateTransformation(p)
      if(!t.transformed(p)||p.transformCharge!==0)throw new Error('activation failed: '+h.id)
      if(!document.querySelector('#transform-widget').classList.contains('active'))throw new Error('HUD active class missing: '+h.id)
      if(!document.querySelector('#jutsu-list').textContent.includes(h.transform.skills[0][0]))throw new Error('transformed skills not rendered: '+h.id)
      const target=s.enemies[1];target.alive=true;target.hp=target.maxHp;target.x=p.x+24;target.y=p.y;p.faceX=1;p.faceY=0
      for(let i=0;i<3;i++){p.skillCD=[0,0,0];p.ch=p.maxCh;const start=p.x;t.castSkill(p,i,target);if(p.ch===p.maxCh)throw new Error('skill not charged/cast: '+h.id+'/'+i);skillCount++;if(h.transform.skills[i][3]==='dash'&&p.x===start)throw new Error('dash did not move: '+h.id)}
      t.setTransformation(p,false)
      if(t.transformed(p)||p.transformCD!==h.transform.cooldown)throw new Error('end/cooldown failed: '+h.id)
      transformedCount++
    }
    // Return to Naruto and confirm the visible mobile control enables and activates.
    p.hero=t.heroes.find(h=>h.id==='naruto');p.maxHp=p.hero.hp;p.hp=p.maxHp;p.transformCharge=100;p.transformCD=0;p.transformTime=0;t.update(.001)
    const button=document.querySelector('#transform-button');const before=button.disabled;button.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:8,pointerType:'touch'}));
    result.mobileActivation={enabled:!before,active:t.transformed(p)}
    result.transformedCount=transformedCount;result.skillCount=skillCount;result.transformedHeroes=transformedHeroes
    return result
  })
  if(!results.hitCharge||!results.defeatCharge||!results.participationCharge||!results.mobileActivation.enabled||!results.mobileActivation.active||errors.length) throw new Error(JSON.stringify({results,errors}))
  console.log(JSON.stringify({results,browserErrors:errors},null,2))
} finally { await browser.close() }

