  const actions=await page.evaluate(()=>{const t=window.__gameTest,{player:p,enemies}=t.get(),out={};let foe=enemies[0];foe.x=p.x+20;foe.y=p.y;p.attackCD=0;document.querySelector('[data-action="attack"]').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:51,pointerType:'touch'}));out.attackCD=p.attackCD;for(let i=1;i<=3;i++){p.ch=p.maxCh;p.skillCD=[0,0,0];let before=p.ch;document.querySelector(`[data-action="skill${i}"]`).dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:51+i,pointerType:'touch'}));out['skill'+i]=before-p.ch}p.transformCharge=100;p.transformCD=0;document.querySelector('#transform-button').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:60,pointerType:'touch'}));out.transformed=t.transformed(p);return out})
