import { createRequire } from 'node:module'
import { join } from 'node:path'
const require=createRequire(join(process.env.HOME,'.local/share/omgithub-playwright/package.json'))
const {chromium}=require('playwright')
const config=await import(join(process.env.HOME,'.local/share/omgithub-playwright/linux.json'),{with:{type:'json'}})
const browser=await chromium.launch({...config.default.browser.launchOptions,headless:true})
try {
 for(const viewport of [{width:390,height:844},{width:844,height:390}]) {
  const page=await browser.newPage({viewport,isMobile:true,hasTouch:true,deviceScaleFactor:1})
  await page.goto('http://127.0.0.1:3002',{waitUntil:'load'})
  await page.locator('#start-button').click()
  await page.waitForTimeout(100)
  const metrics=await page.evaluate(()=>{const name=document.querySelector('#transform-name'),frame=document.querySelector('.arena-frame'),widget=document.querySelector('.transform-widget');return{bodyClass:document.body.className,name:name.textContent,scrollWidth:name.scrollWidth,clientWidth:name.clientWidth,widgetWidth:widget.getBoundingClientRect().width,frame:frame.getBoundingClientRect().toJSON(),screenHeight:innerHeight,documentHeight:document.documentElement.scrollHeight}})
  await page.screenshot({path:`/tmp/opencode/final-${viewport.width}x${viewport.height}.png`})
  console.log(JSON.stringify({viewport,...metrics}))
  await page.close()
 }
} finally {await browser.close()}

